#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Generate src/core/lang/zh_strings.cpp from lang/zh_CN.json."""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "lang", "zh_CN.json")
DST = os.path.join(ROOT, "src", "core", "lang", "zh_strings.cpp")


def cstr(s):
    return json.dumps(s, ensure_ascii=False)


def main():
    with open(SRC, encoding="utf-8") as f:
        data = json.load(f)
    items = sorted(data.items(), key=lambda kv: kv[0].encode("utf-8"))
    lines = [
        "// Generated by tools/gen_zh_lang.py - do not edit.",
        "#if defined(BRUCE_LANG_ZH)",
        '#include "zh_font.h"',
        "",
        f"const uint16_t ZH_STRINGS_COUNT = {len(items)};",
        "",
        "const ZhEntry ZH_STRINGS[] = {",
    ]
    for en, zh in items:
        lines.append(f"    {{{cstr(en)}, {cstr(zh)}}},")
    lines += ["};", "#endif", ""]
    os.makedirs(os.path.dirname(DST), exist_ok=True)
    with open(DST, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines))
    print("wrote", DST, len(items), "entries")


if __name__ == "__main__":
    main()
